112 using TypeInfoRef = std::reference_wrapper<const std::type_info>;
113 
114 struct Hasher
115 {
116     std::size_t operator()(TypeInfoRef code) const
117     {
118         return code.get().hash_code();
119     }
120 };
121 
122 struct EqualTo
123 {
124     bool operator()(TypeInfoRef lhs, TypeInfoRef rhs) const
125     {
126         return lhs.get() == rhs.get();
127     }
128 };
